const STORAGE='memoive-smart-v04-ready';
const SNAPSHOT=`${STORAGE}-snapshot`;
const AI_ENDPOINT=String(window.MEMOIVE_AI_ENDPOINT||'').trim();
const todayIso=()=>{const d=new Date(),offset=d.getTimezoneOffset()*60000;return new Date(d-offset).toISOString().slice(0,10)};
const TODAY=todayIso(),TODAY_DATE=new Date(`${TODAY}T00:00:00`);
function readSaved(){for(const key of[STORAGE,SNAPSHOT]){try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value?.records)return value}catch{}}return null}
const saved=readSaved();
const state={records:DataTools.withExamples(saved?.records||seedRecords,CaseStudies.records),outputs:DataTools.cleanOutputs(saved?.outputs),analytics:DataTools.cleanAnalytics(saved?.analytics),role:saved?.role||'기획자',resurface:saved?.resurface??true,reminderFrequency:saved?.reminderFrequency||'3',reminderTime:saved?.reminderTime||'07:00',lastBackupAt:saved?.lastBackupAt||'',lastNotified:saved?.lastNotified||'',screen:'home',filter:'all',query:'',captureType:'link',currentId:null,currentOutputId:null,pendingDuplicateId:null,calendarYear:TODAY_DATE.getFullYear(),calendarMonth:TODAY_DATE.getMonth(),mediaRecorder:null,mediaStream:null,voiceChunks:[],recognition:null,installPrompt:null,retrying:false};
const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function persist(){const current=localStorage.getItem(STORAGE);if(current)localStorage.setItem(SNAPSHOT,current);localStorage.setItem(STORAGE,JSON.stringify({version:11,records:state.records,outputs:state.outputs,analytics:state.analytics,role:state.role,resurface:state.resurface,reminderFrequency:state.reminderFrequency,reminderTime:state.reminderTime,lastBackupAt:state.lastBackupAt,lastNotified:state.lastNotified}))}
function track(name,{recordId='',type='',value=''}={}){state.analytics.events.push({id:crypto.randomUUID?.()||`event-${Date.now()}-${Math.random()}`,name,at:new Date().toISOString(),recordId,type,value});state.analytics.events=state.analytics.events.slice(-2000);persist()}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function openSheet(id){$('#overlay').classList.add('active');$(id).classList.add('active')}
function closeSheets(){$('#overlay').classList.remove('active');$$('.sheet').forEach(s=>s.classList.remove('active'))}
function go(screen){state.screen=screen;$$('.screen').forEach(s=>s.classList.toggle('active',s.dataset.screen===screen));$$('.bottom-nav [data-go]').forEach(b=>{const selected=b.dataset.go===screen;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('.insights-button').classList.toggle('active',screen==='insights');if(screen==='home')renderHome();if(screen==='library')renderLibrary();if(screen==='topics')renderTopics();if(screen==='calendar')renderCalendar();if(screen==='insights')renderInsights();if(screen==='studio')renderStudio();window.scrollTo(0,0);if(screen==='library')requestAnimationFrame(()=>{$('#record-search').focus();$('#record-search').scrollIntoView({block:'center'})})}
function normalizeUrl(url=''){try{const u=new URL(url);u.hash='';u.searchParams.sort();return (u.origin+u.pathname+u.search).replace(/\/$/,'').toLowerCase()}catch{return url.trim().replace(/\/$/,'').toLowerCase()}}
function recordQuestion(record){const topic=record.topics[0]||'이 내용';const daangn=record.id.includes('daangn');const map={기획자:daangn?'이 기능이 설명 없이도 자연스럽게 사용되는 첫 순간은 언제여야 할까요?':`${topic}을 제품 흐름에 적용한다면 가장 먼저 바꿀 장면은 무엇일까요?`,마케터:daangn?'공지 대신 실제 사용 장면을 보여준 방식을 MEMOIVE 확산에 어떻게 적용할까요?':`${topic}의 가치를 한 문장으로 전달한다면 어떤 메시지가 좋을까요?`,연구자:daangn?'도입 성과를 더 신뢰하려면 어떤 사용 데이터와 비교 기준이 필요할까요?':`${topic}에 대한 이 주장을 검증하려면 어떤 근거가 더 필요할까요?`,'일상 기록자':daangn?'오늘의 작은 불편 중 직접 바꿔보고 싶은 것은 무엇인가요?':`${topic}이 지금 나의 경험과 연결되는 지점은 무엇인가요?`};return map[state.role]||map.기획자}
function dateLabel(iso){const [y,m,d]=iso.split('-').map(Number);return `${m}월 ${d}일`}
function isRhythmDay(date=TODAY_DATE){if(state.reminderFrequency==='daily')return true;const day=date.getDay();return state.reminderFrequency==='1'?day===1:[1,3,5].includes(day)}
function renderHome(){const due=state.records.filter(r=>r.revisitOn&&r.revisitOn<=TODAY).sort((a,b)=>a.revisitOn.localeCompare(b.revisitOn))[0]||state.records[1]||state.records[0];$('#home-output-count').textContent=state.outputs.length?`${state.outputs.length}개의 결과물을 이어 쓰고 있어요`:'아직 만든 결과물이 없어요';$('#resurface-card').classList.toggle('hidden',!state.resurface||!due||!isRhythmDay());if(!due)return;const reason=due.revisitOn&&due.revisitOn<=TODAY?'직접 다시 보기로 정한 기록':'최근 생각과 연결되는 기록';$('#resurface-date').textContent=due.revisitOn===TODAY?'오늘 다시 보기':`${dateLabel(due.savedAt)}의 기록`;$('#resurface-record').dataset.recordId=due.id;$('#resurface-record').innerHTML=`<span class="record-symbol">${esc(due.label)}</span><span><strong>${esc(due.title)}</strong><small>${esc(reason)} · ${esc(due.thought||'아직 내 생각이 없어요.')}</small></span><b>→</b>`;$('#home-records').innerHTML=state.records.slice(0,2).map(r=>`<button class="home-card" data-record-id="${r.id}"><span class="home-cover"><span>${esc(r.label)} · ${dateLabel(r.savedAt)}</span><b>${esc(r.topics[0]||'새 기록')}</b></span><strong>${esc(r.title)}</strong><small>${r.thought?'내 생각 있음':'이어 쓰기'}</small></button>`).join('');bindRecordButtons()}
function filteredRecords(){return state.records.filter(r=>(state.filter==='all'||r.type===state.filter)&&DataTools.matchesQuery(r,state.query))}
function recordRow(r,cls='record-item'){return `<button class="${cls}" data-record-id="${esc(r.id)}"><span class="record-thumb">${DataTools.isExample(r)?'예시':esc(r.label)}</span><span><strong>${esc(r.title)}</strong><small>${dateLabel(r.savedAt)} 저장 · ${esc(r.source)} · ${r.thought?'내 생각 있음':'이어 쓰기'}</small></span><b>→</b></button>`}
function renderLibrary(){const list=filteredRecords(),q=state.query.trim();$('#record-list').innerHTML=list.map(r=>recordRow(r)).join('');$('#empty-state').classList.toggle('hidden',list.length>0);$('#search-status').textContent=q?`‘${q}’ 검색 결과 ${list.length}개 · 최신순`:`전체 기록 ${list.length}개 · 최신순`;bindRecordButtons()}
function topicCounts(){const counts={};state.records.forEach(r=>r.topics.forEach(t=>counts[t]=(counts[t]||0)+1));return Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
function renderTopics(){const entries=topicCounts();$('#topic-grid').innerHTML=entries.map(([name,count])=>`<button class="topic-card" data-topic="${esc(name)}"><span>${String(count).padStart(2,'0')}</span><strong>${esc(name)}</strong><small>${count===entries[0][1]?'가장 자주 기록한 주제':'관련 기록 보기'}</small></button>`).join('');$$('.topic-card').forEach(b=>b.onclick=()=>openTopic(b.dataset.topic))}
function openTopic(topic){const list=state.records.filter(r=>r.topics.includes(topic));$('#topic-title').textContent=topic;$('#topic-description').textContent=`${list.length}개의 기록에서 이 관심사가 반복됐어요.`;$('#topic-record-list').innerHTML=list.map(r=>recordRow(r,'sheet-record')).join('');openSheet('#topic-sheet');bindRecordButtons()}
function monthRecords(){return state.records.filter(r=>{const [y,m]=r.savedAt.split('-').map(Number);return y===state.calendarYear&&m===state.calendarMonth+1})}
function renderCalendar(){const names=['1월','2월','3월','4월','5월','6월','7월','8월','9월','10월','11월','12월'];const list=monthRecords();$('#calendar-title').textContent=`${state.calendarYear}년 ${names[state.calendarMonth]}`;$('#calendar-count').textContent=list.length?`${list.length}개의 기록`:'아직 기록이 없어요';const grouped={};list.forEach(r=>{const d=Number(r.savedAt.slice(8,10));(grouped[d]??=[]).push(r)});const first=(new Date(state.calendarYear,state.calendarMonth,1).getDay()+6)%7,days=new Date(state.calendarYear,state.calendarMonth+1,0).getDate();let html='';for(let i=0;i<first;i++)html+='<span></span>';for(let d=1;d<=days;d++){const n=grouped[d]?.length||0,today=state.calendarYear===TODAY_DATE.getFullYear()&&state.calendarMonth===TODAY_DATE.getMonth()&&d===TODAY_DATE.getDate();html+=`<button data-day="${d}" class="${n?'has-records':''} ${today?'today':''}"><b>${d}</b>${n>1?`<em>${n}</em>`:''}</button>`}$('#calendar-grid').innerHTML=html;$('#month-record-list').innerHTML=list.length?list.sort((a,b)=>b.savedAt.localeCompare(a.savedAt)).map(r=>`<button class="month-record" data-record-id="${r.id}"><time>${r.savedAt.slice(8,10)}</time><span><strong>${esc(r.title)}</strong><small>${esc(r.source)}</small></span><b>→</b></button>`).join(''):'<div class="empty">이달에 남긴 기록이 없어요.</div>';$$('#calendar-grid button').forEach(b=>b.onclick=()=>openDay(Number(b.dataset.day),grouped[Number(b.dataset.day)]||[]));bindRecordButtons()}
function openDay(day,records){$('#day-title').textContent=`${state.calendarMonth+1}월 ${day}일의 기록`;$('#day-record-list').innerHTML=records.length?records.map(r=>recordRow(r,'sheet-record')).join(''):'<div class="empty">이날은 기록을 쉬었어요.</div>';openSheet('#day-sheet');bindRecordButtons()}
function renderInsights(){const summary=DataTools.analyticsSummary(state.records,state.analytics.events,state.outputs),labels={article:'링크·기사',video:'영상',image:'이미지',voice:'음성',text:'텍스트'},entries=Object.entries(summary.typeCounts).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(([,count])=>count));$('#metric-total').textContent=summary.total;$('#metric-revisit').textContent=`${summary.revisitRate}%`;$('#metric-revisit-count').textContent=`${summary.openedCount}개 다시 봄`;$('#metric-thought').textContent=`${summary.thoughtRate}%`;$('#metric-quality').textContent=summary.ratingCount?`${summary.helpfulRate}%`:'—';$('#metric-quality-count').textContent=summary.ratingCount?`${summary.ratingCount}개 평가`:'평가 전';$('#metric-conversion').textContent=`${summary.conversionRate}%`;$('#metric-output-count').textContent=`${summary.outputCount}개`;$('#metric-used-output').textContent=`${summary.usedOutputCount}개`;$('#metric-reuse').textContent=`${summary.reuseCount}회`;$('#capture-mix').innerHTML=entries.map(([type,count])=>`<div class="bar-row"><div><strong>${labels[type]||esc(type)}</strong><span>${count}개</span></div><div class="bar-track" role="img" aria-label="${labels[type]||esc(type)} 기록 ${count}개"><i style="width:${Math.round(count/max*100)}%"></i></div></div>`).join('')||'<p class="analysis-note">기록을 추가하면 입력 방식별 분포가 보여요.</p>';const top=entries[0];$('#behavior-insight').textContent=summary.outputCount?`${summary.convertedCount}개의 영감이 ${summary.outputCount}개의 결과물에 쓰였어요. 다음에는 아직 활용하지 않은 기록을 골라보세요.`:!summary.openedCount?'아직 다시 연 기록이나 결과물이 없어요. 기록 하나에서 첫 결과물을 만들어보세요.':`저장한 기록 중 ${summary.revisitRate}%를 다시 봤어요. 이제 다시 본 기록을 결과물로 이어가보세요.`;$('#quality-meter-bar').style.width=`${summary.helpfulRate}%`;$('#quality-insight').textContent=!summary.ratingCount?'각 기록 상세에서 요약이 도움됐는지 평가하면 품질 신호가 여기에 쌓여요.':`평가 ${summary.ratingCount}개 중 ${summary.helpfulRate}%가 요약이 도움됐다고 답했어요.${top?` 가장 많이 쌓인 형식은 ${labels[top[0]]||top[0]}예요.`:''}`}

function outputTypeLabel(type){return({idea:'아이디어 메모',article:'블로그·뉴스레터',social:'인스타그램 게시물',social_post:'인스타그램 게시물',social_story:'인스타그램 스토리',proposal:'업무 제안서',project:'프로젝트 기획안'})[type]||'결과물'}
function renderStudio(){const summary=DataTools.analyticsSummary(state.records,state.analytics.events,state.outputs);$('#studio-source-count').textContent=summary.total;$('#studio-output-count').textContent=summary.outputCount;$('#studio-progress-note').textContent=state.outputs.length?`${summary.conversionRate}%의 영감이 결과물로 이어졌어요. 출처를 따라가며 언제든 다시 다듬을 수 있어요.`:'예시를 제외한 기록을 집계해요. 첫 결과물은 기록 하나로도 충분해요.';$('#output-empty').classList.toggle('hidden',state.outputs.length>0);$('#output-list').innerHTML=state.outputs.map(output=>`<button class="output-card" data-output-id="${esc(output.id)}"><span><small>${esc(outputTypeLabel(output.type))} · ${dateLabel(output.updatedAt.slice(0,10))}</small><strong>${esc(output.title)}</strong><em>${output.sourceRecordIds.length}개의 영감 사용</em></span><b>→</b></button>`).join('');$$('[data-output-id]').forEach(button=>button.onclick=()=>openCreator({outputId:button.dataset.outputId}))}
function openCreator({recordIds=[],outputId=null}={}){const output=state.outputs.find(item=>item.id===outputId);state.currentOutputId=output?.id||null;$('#creator-form').reset();$('#creator-draft').classList.toggle('hidden',!output);$('#creator-step').textContent=output?'결과물 다시 다듬기':'1 / 3 · 영감 선택';$('#creator-title').innerHTML=output?'저장한 결과물을<br>이어 써보세요.':'어떤 결과물로<br>이어갈까요?';$('#output-type').value=output?.type||'social_post';$('#output-tone').value=output?.tone||'insight';$('#output-purpose').value=output?.purpose||'';$('#output-viewpoint').value=output?.viewpoint||'';const selected=new Set(output?.sourceRecordIds||recordIds);$('#creator-sources').innerHTML=creatorSourceOptions(selected);$('#output-title').value=output?.title||'';$('#output-body').value=output?.body||'';$('#output-used').checked=Boolean(output?.usedAt);$('#output-use-note').value=output?.useNote||'';$('#output-use-fields').hidden=!output?.usedAt;$('#case-proposal-note').hidden=true;renderOutputSources(output?.sourceRecordIds||recordIds);setShareFormat(output?.shareFormat||(output?.type==='social_story'?'story':'post'));if(output)refreshOutputPreview();$('#detail-view').classList.remove('active');$('#creator-view').classList.add('active');$('#creator-view').scrollTop=0}
function selectedCreatorRecords(){const ids=$$('#creator-sources input:checked').map(input=>input.value);return state.records.filter(record=>ids.includes(record.id))}
function renderOutputSources(ids){const records=state.records.filter(record=>ids.includes(record.id));$('#output-sources').innerHTML=`<p class="eyebrow">참고 기록과 내 생각</p>${records.map(record=>`<details class="source-trace"><summary>${esc(record.title)}</summary><p><strong>참고한 내용</strong><br>${esc(record.summary)}</p><p><strong>그때 남긴 내 생각</strong><br>${esc(record.thought||'아직 작성하지 않았어요.')}</p>${LinkReader.validateHttpUrl(record.url)?`<a href="${esc(record.url)}" target="_blank" rel="noopener noreferrer">원문 열기 (새 탭)</a>`:''}</details>`).join('')}`}
function aiPayload({records,draft=null}){return{type:$('#output-type').value,tone:$('#output-tone').value,purpose:$('#output-purpose').value.trim(),viewpoint:$('#output-viewpoint').value.trim(),records:records.map(record=>({title:record.title,source:record.source,url:record.url,summary:record.summary,points:record.points,thought:record.thought,uncertainty:record.uncertainty})),draft}}
async function requestAiDraft(payload){if(!AI_ENDPOINT)throw Object.assign(new Error('AI 연결 전'),{code:'AI_NOT_CONNECTED'});const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(AI_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(data.message||'AI 응답을 받지 못했어요.'),{status:response.status});if(typeof data.title!=='string'||typeof data.body!=='string'||!data.title.trim()||!data.body.trim())throw new Error('완성된 초안을 받지 못했어요.');return data}finally{clearTimeout(timer)}}
function applyOutputDraft(result,records,type){$('#output-title').value=result.title;$('#output-body').value=result.body;renderOutputSources(records.map(record=>record.id));setShareFormat(type==='social_story'?'story':'post');$('#creator-draft').classList.remove('hidden');$('#creator-step').textContent='2 / 3 · 직접 다듬기';refreshOutputPreview();requestAnimationFrame(()=>$('#creator-draft').scrollIntoView({behavior:'smooth',block:'start'}))}
async function generateOutput(event){event.preventDefault();const records=selectedCreatorRecords(),purpose=$('#output-purpose').value.trim(),viewpoint=$('#output-viewpoint').value.trim(),type=$('#output-type').value,tone=$('#output-tone').value;if(!records.length)return toast('결과물에 사용할 영감을 하나 이상 골라주세요.');if(!viewpoint)return toast('나의 관점을 한 문장 적어주세요.');const button=$('#generate-output'),status=$('#ai-status'),localDraft=DataTools.buildDraft({type,tone,purpose,viewpoint,records});button.disabled=true;button.setAttribute('aria-busy','true');status.textContent=AI_ENDPOINT?'Gemini가 기록과 내 관점을 구분해 초안을 만드는 중이에요.':'Gemini 연결 전이라 기기 안의 기본 초안을 만들고 있어요.';try{const result=await requestAiDraft(aiPayload({records}));applyOutputDraft(result,records,type);status.textContent=`${result.model||'Gemini'}로 초안을 만들었어요. 직접 고쳐도 원본 기록은 그대로예요.`;track('ai_output_generated',{value:type})}catch(error){if($('#output-body').value.trim() && AI_ENDPOINT){status.textContent='AI 응답을 받지 못해 작성 중인 글을 그대로 유지했어요.';return;}applyOutputDraft(localDraft,records,type);status.textContent=error.code==='AI_NOT_CONNECTED'?'Gemini 연결 전이라 기본 초안을 만들었어요. 연결 후에는 같은 화면에서 AI 초안을 받을 수 있어요.':error.status===429?'무료 사용 한도에 잠시 도달해 기본 초안으로 전환했어요.':'연결이 불안정해 기본 초안을 만들었어요. 원본 기록은 그대로예요.';track('output_fallback_used',{value:String(error.status||error.code||'network')})}finally{button.disabled=false;button.removeAttribute('aria-busy')}track('output_drafted',{value:type})}
async function refineOutputWithAi(){const records=selectedCreatorRecords(),title=$('#output-title').value.trim(),body=$('#output-body').value.trim();if(!title||!body)return toast('먼저 초안을 만들어주세요.');if(!AI_ENDPOINT)return toast('Gemini 연결이 완료되면 사용할 수 있어요. 현재 글은 그대로 보존했어요.');const button=$('#ai-refine-output');button.disabled=true;button.setAttribute('aria-busy','true');try{const result=await requestAiDraft(aiPayload({records,draft:{title,body}}));$('#output-title').value=result.title;$('#output-body').value=result.body;refreshOutputPreview();track('ai_output_refined',{value:$('#output-type').value});toast('Gemini 제안을 반영했어요. 원하면 다시 직접 고칠 수 있어요.')}catch(error){toast(error.status===429?'무료 사용 한도에 잠시 도달했어요. 현재 글은 그대로예요.':'다듬기 요청에 실패했어요. 현재 글은 그대로예요.')}finally{button.disabled=false;button.removeAttribute('aria-busy')}}
function saveOutput(){
  const records=selectedCreatorRecords(),title=$('#output-title').value.trim(),body=$('#output-body').value.trim(),used=$('#output-used').checked,useNote=$('#output-use-note').value.trim();
  if(!records.length||!title||!body)return toast('영감, 제목, 내용을 확인해 주세요.');
  if(used&&!useNote){$('#output-use-note').focus();return toast('어디에 어떻게 썼는지 한 줄 남겨주세요.');}
  const now=new Date().toISOString(),existing=state.outputs.find(item=>item.id===state.currentOutputId);
  const output={...existing,id:existing?.id||(crypto.randomUUID?.()||`output-${Date.now()}`),type:$('#output-type').value,tone:$('#output-tone').value,shareFormat:currentShareFormat(),purpose:$('#output-purpose').value.trim(),viewpoint:$('#output-viewpoint').value.trim(),title,body,sourceRecordIds:records.map(record=>record.id),createdAt:existing?.createdAt||now,updatedAt:now,usedAt:used?(existing?.usedAt||now):'',useNote};
  const previous=state.outputs;state.outputs=existing?state.outputs.map(item=>item.id===output.id?output:item):[output,...state.outputs];
  try{persist();}catch{state.outputs=previous;toast('저장 공간을 확인해 주세요. 작성한 글은 이 화면에 남아 있어요.');return;}
  try{track('output_saved',{value:output.type});}catch{}
  $('#creator-view').classList.remove('active');go('studio');toast(existing?'결과물과 활용 기록을 다시 저장했어요.':'영감을 나의 결과물로 저장했어요.');
}
async function copyOutput(){const body=$('#output-body').value.trim();if(!body)return toast('먼저 초안을 만들어주세요.');try{await navigator.clipboard.writeText(`# ${$('#output-title').value.trim()}\n\n${body}`);track('output_copied',{value:$('#output-type').value});toast('결과물을 복사했어요.')}catch{toast('복사하지 못했어요. 브라우저 권한을 확인해 주세요.')}}
function currentShareFormat(){return $('.share-format button.active')?.dataset.shareFormat||'post'}
function setShareFormat(format='post'){$$('.share-format button').forEach(button=>{const active=button.dataset.shareFormat===format;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});renderShareCard()}
function outputQuality(){const title=$('#output-title').value.trim(),body=$('#output-body').value.trim(),type=$('#output-type').value,tone=$('#output-tone').value,viewpoint=$('#output-viewpoint').value.trim(),records=selectedCreatorRecords(),lines=body.split('\n').map(line=>line.replace(/^#+\s*|^-\s*/g,'').trim()).filter(Boolean),normalized=lines.map(line=>line.replace(/[\s.!?。]+/g,'').toLowerCase()),uniqueCount=new Set(normalized).size,limits={social_story:[60,420],social_post:[140,900],article:[350,3500],proposal:[220,3000],project:[220,3000],idea:[120,1800]}[type]||[120,1800],first=lines[0]||'';return[{label:`채널에 어울리는 길이예요 (${body.length}자)`,help:`지금은 ${body.length}자예요. 이 채널에서는 ${limits[0]}~${limits[1]}자가 읽기 편해요.`,pass:body.length>=limits[0]&&body.length<=limits[1]},{label:'반복된 마침표·쉼표가 없어요',help:'겹친 마침표나 어색한 문장 끝을 한 번 살펴보세요.',pass:Boolean(tone)&&!/[.]{2,}|,,/.test(body)},{label:'제목과 첫 문장의 길이를 확인했어요',help:'제목과 첫 문장에 핵심 생각을 조금 더 구체적으로 적어보세요.',pass:title.length>=8&&title.length<=40&&first.length>=12&&first.length<=85},{label:'같은 문장이 반복되지 않아요',help:'비슷하게 반복되는 문장을 하나 덜어내도 좋아요.',pass:normalized.length===uniqueCount},{label:'내 관점 항목과 선택한 기록이 있어요',help:'참고한 내용과 나의 관점을 나누어 적으면 더 분명해져요.',pass:Boolean(viewpoint)&&records.length>0&&/나의 관점/.test(body)},{label:'다음 행동 관련 표현이 있어요',help:'읽은 뒤 해볼 작은 행동을 덧붙여도 좋아요.',pass:/다음|시작|실행|실험|한 걸음/.test(body)}]}
function renderOutputQuality(){const checks=outputQuality(),score=checks.filter(item=>item.pass).length;$('#output-quality-score').textContent=`${score}개 준비됨`;$('#output-quality-list').innerHTML=checks.map(item=>`<div class="quality-item ${item.pass?'pass':''}"><span>${esc(item.pass?item.label:item.help)}</span></div>`).join('');return score}
function canvasLines(ctx,text,maxWidth){const chars=[...String(text).replace(/\s+/g,' ').trim()],lines=[];let line='';for(const char of chars){const test=line+char;if(line&&ctx.measureText(test).width>maxWidth){lines.push(line.trim());line=char}else line=test}if(line.trim())lines.push(line.trim());return lines}
function drawCanvasText(ctx,text,x,y,maxWidth,lineHeight,maxLines){const lines=canvasLines(ctx,text,maxWidth).slice(0,maxLines);lines.forEach((line,index)=>ctx.fillText(index===maxLines-1&&canvasLines(ctx,text,maxWidth).length>maxLines?`${line.replace(/[.…]+$/,'')}…`:line,x,y+index*lineHeight));return y+lines.length*lineHeight}
function cleanShareText(value=''){return value.replace(/^#+\s*/gm,'').replace(/^-\s*/gm,'').replace(/\n{2,}/g,'\n').trim()}
function renderShareCard(){const canvas=$('#share-card-preview');if(!canvas)return;const format=currentShareFormat(),story=format==='story',width=1080,height=story?1920:1350;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d'),pad=story?92:78,title=$('#output-title').value.trim()||'영감에서 시작한 새로운 생각',body=cleanShareText($('#output-body').value),view=$('#output-viewpoint').value.trim()||'기록에서 발견한 나만의 관점',records=selectedCreatorRecords(),source=records.slice(0,2).map(record=>record.source||record.title).join(' · ')||'MEMOIVE 기록';ctx.fillStyle='#f4efe6';ctx.fillRect(0,0,width,height);ctx.fillStyle='#34241e';ctx.fillRect(0,0,width,story?330:260);ctx.fillStyle='#fffdf9';ctx.font=`700 ${story?30:27}px "Noto Sans KR"`;ctx.letterSpacing='5px';ctx.fillText('MEMOIVE  ·  INSPIRATION CARD',pad,story?105:88);ctx.letterSpacing='0px';ctx.font=`700 ${story?72:62}px "Gowun Batang"`;drawCanvasText(ctx,title,pad,story?190:150,width-pad*2,story?94:80,2);const first=body.split('\n').map(line=>line.trim()).find(line=>line&&!/^(기록에서|나의 관점|다음 행동|다음 한 걸음)/.test(line))||view;ctx.fillStyle='#725343';ctx.font=`700 ${story?60:49}px "Gowun Batang"`;const quoteY=story?535:420,quoteEnd=drawCanvasText(ctx,first,pad,quoteY,width-pad*2,story?84:68,story?4:3);ctx.fillStyle='#b8957c';ctx.fillRect(pad,quoteEnd+34,90,6);ctx.fillStyle='#725343';ctx.font=`700 ${story?24:20}px "Noto Sans KR"`;ctx.fillText('MY PERSPECTIVE',pad,quoteEnd+112);ctx.fillStyle='#2b211d';ctx.font=`500 ${story?39:32}px "Noto Sans KR"`;drawCanvasText(ctx,view,pad,quoteEnd+175,width-pad*2,story?62:50,story?6:4);ctx.fillStyle='#e8ddd0';ctx.fillRect(pad,height-(story?300:235),width-pad*2,2);ctx.fillStyle='#7f746d';ctx.font=`500 ${story?24:20}px "Noto Sans KR"`;ctx.fillText('SOURCE',pad,height-(story?225:170));ctx.fillStyle='#34241e';ctx.font=`500 ${story?27:22}px "Noto Sans KR"`;drawCanvasText(ctx,source,pad,height-(story?170:120),width-pad*2,story?40:34,2);ctx.fillStyle='#725343';ctx.beginPath();ctx.arc(width-pad-28,height-(story?205:150),28,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font=`700 ${story?30:25}px "Gowun Batang"`;ctx.textAlign='center';ctx.fillText('m',width-pad-28,height-(story?195:142));ctx.textAlign='left'}
function refreshOutputPreview(){renderOutputQuality();renderShareCard()}
function shareCardBlob(){return new Promise((resolve,reject)=>$('#share-card-preview').toBlob(blob=>blob?resolve(blob):reject(new Error('이미지를 만들지 못했어요.')),'image/png',1))}
function shareCardName(){return`memoive-${currentShareFormat()}-${TODAY}.png`}
async function downloadShareCard(){try{const blob=await shareCardBlob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=shareCardName();link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);track('output_card_downloaded',{value:currentShareFormat()});toast('공유 카드 이미지를 저장했어요.')}catch{toast('이미지를 저장하지 못했어요.')}}
async function shareCardNative(){renderOutputQuality();try{const blob=await shareCardBlob(),file=new File([blob],shareCardName(),{type:'image/png'}),data={files:[file],title:$('#output-title').value.trim(),text:$('#output-body').value.trim()};if(navigator.canShare?.({files:[file]})){await navigator.share(data);track('output_card_shared',{value:currentShareFormat()});toast('공유 메뉴를 열었어요. 인스타그램을 선택해 주세요.')}else await downloadShareCard()}catch(error){if(error?.name!=='AbortError'){await downloadShareCard();toast('공유 대신 이미지를 저장했어요.')}}}
async function copyShareCaption(){const records=selectedCreatorRecords(),sources=records.map(record=>record.url||record.source).filter(Boolean).join('\n'),caption=`${$('#output-title').value.trim()}\n\n${$('#output-body').value.trim()}${sources?`\n\n참고한 기록\n${sources}`:''}`;try{await navigator.clipboard.writeText(caption);track('output_caption_copied',{value:$('#output-type').value});toast('게시물 캡션을 복사했어요.')}catch{toast('캡션을 복사하지 못했어요.')}}
function bindRecordButtons(){$$('[data-record-id]').forEach(b=>b.onclick=()=>{closeSheets();openRecord(b.dataset.recordId)})}
function confidenceLabel(n){return n>0?'자동 정리 · 원문 확인 권장':'본문 확인 전'}
function openRecord(id,{trackOpen=true}={}){const r=state.records.find(x=>x.id===id);if(!r)return;state.currentId=id;if(trackOpen)track('record_opened',{recordId:r.id,type:r.type});$('#detail-type').textContent=DataTools.isExample(r)?'예시 · '+r.label:r.label;const sourceLabel=CaseStudies.records.some(item=>item.id===r.id)?(r.id==='example-musinsa-experience'?'제공된 본문 확인':'공개 원문 확인'):confidenceLabel(r.confidence);$('#detail-confidence').textContent=sourceLabel;$('#detail-title').textContent=r.title;$('#detail-source').textContent=`${r.source} · ${r.sourceDate}`;$('#detail-tags').innerHTML=r.topics.map(t=>`<span>${esc(t)}</span>`).join('');$('#detail-summary').textContent=r.summary;$$('.summary-rating button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.rating===r.summaryRating)));$('#detail-points').innerHTML=r.points.map(p=>`<li>${esc(p)}</li>`).join('');$('#detail-evidence').innerHTML=r.evidence.map(e=>`<div class="evidence-item"><strong>${esc(e.label)}</strong><small>${esc(e.text)}</small></div>`).join('');$('#evidence-confidence').textContent=sourceLabel;$('#uncertainty-note').textContent=r.uncertainty;$('#detail-quote').textContent=r.quote?`“${r.quote}”`:'';$('#detail-quote').hidden=!r.quote;renderRecordProgress(r);$('#question-role').textContent=state.role;$('#detail-question').textContent=recordQuestion(r);$('#detail-thought').textContent=r.thought||'아직 나만의 기록이 없어요. 한 문장이면 충분해요.';$('#action-section').classList.toggle('hidden',!r.actions?.length);$('#detail-actions').innerHTML=(r.actions||[]).map(a=>`<span>${esc(a)}</span>`).join('');$('#retry-source').classList.toggle('hidden',r.fetchStatus!=='failed');$('#source-link').href=r.url||'#';$('#source-link').style.display=r.url?'flex':'none';$('#revisit-select').value=revisitDays(r.revisitOn);renderRelated(r);$('#detail-view').classList.add('active');$('#detail-view').scrollTop=0}
function revisitDays(iso){if(!iso)return'0';const b=new Date(iso+'T00:00:00'),d=Math.round((b-TODAY_DATE)/86400000);return [3,7,30].includes(d)?String(d):'0'}
function renderRelated(record){const related=DataTools.relatedRecords(record,state.records);$('#related-reason').textContent=related.length?related[0].reason:'연결할 기록이 더 쌓이면 여기에서 함께 보여드릴게요.';$('#related-records').innerHTML=related.length?related.map(item=>`<button class="related-record" data-record-id="${esc(item.record.id)}"><span><strong>${esc(item.record.title)}</strong><small>${esc(item.reason)}</small></span><b>→</b></button>`).join(''):'<p class="related-empty">아직 뚜렷하게 이어지는 기록이 없어요.</p>';bindRecordButtons()}
async function copyCurrentRecord(){const record=state.records.find(item=>item.id===state.currentId);if(!record)return;const markdown=DataTools.toMarkdown(record);try{await navigator.clipboard.writeText(markdown);track('record_reused',{recordId:record.id,type:record.type});toast('글쓰기용 기록을 복사했어요.')}catch{toast('복사하지 못했어요. 브라우저 권한을 확인해 주세요.')}}
function openThought(id){const r=state.records.find(x=>x.id===id);if(!r)return;state.currentId=id;$('#thought-question').textContent=recordQuestion(r);$('#thought-input').value=r.thought||'';openSheet('#thought-sheet')}
function saveThought(){const v=$('#thought-input').value.trim();if(!v)return toast('한 문장만 남겨주세요.');const r=state.records.find(x=>x.id===state.currentId);r.thought=v;track('thought_saved',{recordId:r.id,type:r.type});closeSheets();openRecord(r.id,{trackOpen:false});toast('나만의 기록을 저장했어요.')}
function rateSummary(value){const r=state.records.find(x=>x.id===state.currentId);if(!r)return;r.summaryRating=value;track('summary_rated',{recordId:r.id,type:r.type,value});$$('.summary-rating button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.rating===value)));toast(value==='helpful'?'도움됐다는 평가를 남겼어요.':'아쉬운 점을 다음 개선에 반영할게요.')}
function selectCaptureType(type){state.captureType=type;$$('.capture-types button').forEach(b=>b.classList.toggle('active',b.dataset.type===type));$$('.capture-panel').forEach(p=>p.classList.toggle('active',p.dataset.panel===type))}
function daangnCopy(note=''){const r=structuredClone(seedRecords[0]);r.id='daangn-'+Date.now();r.savedAt=todayIso();r.capturedAt=new Date().toISOString();if(note)r.thought=note;return r}
function genericRecord(type,raw,note){const label={link:'ARTICLE',image:'IMAGE',text:'TEXT',voice:'VOICE'}[type],isVoice=type==='voice',isImage=type==='image',source=type==='link'?safeHost(raw):type==='image'?'업로드한 이미지':type==='voice'?'새 음성 메모':'직접 작성한 글';const clean=raw.trim();return{id:'record-'+Date.now(),type:type==='link'?'article':type,label,savedAt:todayIso(),capturedAt:new Date().toISOString(),sourceDate:TODAY.replaceAll('-','.'),title:isImage?'이미지에서 발견한 새로운 레퍼런스':isVoice?(clean.slice(0,34)||'새로 남긴 음성 아이디어'):(clean.slice(0,38)||'새로 저장한 콘텐츠'),source,url:type==='link'?raw:'',summary:isImage?'이미지에서 읽은 문자와 시각 정보를 바탕으로 다시 찾기 쉬운 기록으로 정리한 시연 결과예요.':isVoice?'말한 내용을 글로 옮기고 중심 생각과 다음 행동을 구분한 기록이에요.':clean||'공유한 콘텐츠의 중심 내용을 다시 찾기 쉽게 정리한 시연 결과예요.',points:isVoice?['음성 원본을 브라우저에서 녹음했어요.','변환된 문장에서 중심 생각을 찾았어요.','행동을 나타내는 문장을 분리했어요.']:isImage?['선택한 이미지 원본을 확인했어요.','추출된 문자를 사용자가 수정할 수 있어요.','내용을 연결할 주제를 제안했어요.']:clean.split(/(?<=[.!?])\s+|\n/).map(line=>line.trim()).filter(Boolean).slice(0,3),quote:clean.slice(0,80)||'떠오른 순간을 남기는 것이 기록의 시작이다.',thought:note,topics:isVoice?['음성','아이디어']:isImage?['이미지','레퍼런스']:['새로운 기록'],confidence:type==='text'?96:68,uncertainty:type==='text'?'사용자가 직접 작성한 원문을 구조화했어요.':'실제 AI 서버가 연결되지 않은 시연 분석이므로 원문 확인이 필요해요.',evidence:[{label:isImage?'추출 문자':isVoice?'음성 변환 내용':'입력 원문',text:clean||'자동으로 확인된 문장이 없어 사용자의 검토가 필요해요.'}],revisitOn:'',actions:extractActions(clean)} }
function safeHost(url){try{return new URL(url).hostname.replace('www.','')}catch{return'공유한 링크'}}
function extractActions(text){return text.split(/[.!?\n]/).map(s=>s.trim()).filter(s=>/(해야|하기|만들|확인|작성|적용|보내)/.test(s)).slice(0,3)}
function pendingLinkRecord(url,note){return{id:crypto.randomUUID?.()||`record-${Date.now()}`,type:'article',label:'ARTICLE',savedAt:todayIso(),capturedAt:new Date().toISOString(),sourceDate:TODAY.replaceAll('-','.'),title:`${safeHost(url)} 링크`,source:safeHost(url),url,summary:'원문 주소를 먼저 보존했어요. 지금 본문을 읽고 있습니다.',points:['입력한 원문 주소를 기기에 먼저 저장했어요.'],quote:note||'원문을 읽는 중이에요.',thought:note,topics:['새로운 기록'],confidence:0,uncertainty:'본문 확인 전이에요.',evidence:[{label:'보존한 원문',text:url}],revisitOn:'',actions:[],fetchStatus:'reading'}}
function failedLinkRecord(record){Object.assign(record,{title:`${safeHost(record.url)}에서 저장한 링크`,summary:'원문 주소와 내 생각은 보존했지만 본문을 자동으로 읽지 못했어요.',points:['원문 주소는 기기에 저장되어 있어요.','아래 원문 링크를 직접 열거나 원문 다시 읽기를 눌러주세요.'],quote:record.thought||'읽기에 실패해도 원문 주소는 보존됩니다.',topics:['읽기 대기'],confidence:0,uncertainty:'로그인 전용 페이지, 접근 제한 또는 일시적인 네트워크 문제일 수 있어요.',evidence:[{label:'보존한 원문',text:record.url}],fetchStatus:'failed'})}
function publishedDate(value){const date=value.match(/\d{4}-\d{2}-\d{2}/)?.[0];return date?date.replaceAll('-','.'):TODAY.replaceAll('-','.')}
async function readLink(record){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const response=await fetch(LinkReader.readerUrl(record.url),{headers:{Accept:'text/plain'},signal:controller.signal});if(!response.ok)throw new Error(`원문 응답 ${response.status}`);const parsed=LinkReader.parseReaderText(await response.text(),record.url),result=LinkReader.summarize(parsed.content,parsed.title),confidence=parsed.content.length>3000?92:84;Object.assign(record,{title:parsed.title.slice(0,100),source:safeHost(record.url),sourceDate:publishedDate(parsed.published),summary:result.summary,points:result.points,quote:result.quote,topics:['웹 기록'],confidence,uncertainty:'공개 원문에서 자동으로 고른 핵심 문장이에요. 중요한 판단은 원문과 함께 확인해 주세요.',evidence:result.evidence,actions:extractActions(parsed.content),fetchStatus:'ready'})}finally{clearTimeout(timer)}}
async function finishLinkRecord(record){try{await readLink(record);toast('실제 원문과 근거를 기록했어요.')}catch{failedLinkRecord(record);toast('주소는 저장했어요. 원문은 나중에 다시 읽을 수 있어요.')}persist();renderAll();openRecord(record.id,{trackOpen:false})}
async function retrySource(){const record=state.records.find(r=>r.id===state.currentId);if(!record?.url)return;record.fetchStatus='reading';persist();$('#detail-view').classList.remove('active');$('#analyzing').classList.add('active');try{await finishLinkRecord(record)}finally{$('#analyzing').classList.remove('active')}}
async function submitCapture(event){event.preventDefault();let raw='';if(state.captureType==='link')raw=$('#capture-link').value.trim();if(state.captureType==='text')raw=$('#capture-text').value.trim();if(state.captureType==='image')raw=$('#image-extracted').value.trim();if(state.captureType==='voice')raw=$('#voice-transcript').value.trim();if(!raw&&state.captureType!=='image')return toast('정리할 내용을 입력해 주세요.');if(state.captureType==='link'){const valid=LinkReader.validateHttpUrl(raw);if(!valid){$('#link-status').textContent='http 또는 https로 시작하는 공개 주소를 입력해 주세요.';$('#capture-link').focus();return}raw=valid;$('#link-status').textContent='';const dup=state.records.find(r=>r.url&&normalizeUrl(r.url)===normalizeUrl(raw));if(dup){state.pendingDuplicateId=dup.id;$('#duplicate-card').innerHTML=`<strong>${esc(dup.title)}</strong><small>${esc(dup.source)} · ${dateLabel(dup.savedAt)}에 저장</small>`;closeSheets();setTimeout(()=>openSheet('#duplicate-sheet'),100);return}}const note=$('#capture-note').value.trim(),button=$('#capture-submit');button.disabled=true;button.setAttribute('aria-busy','true');closeSheets();$('#analyzing').classList.add('active');try{if(state.captureType==='link'){const record=pendingLinkRecord(raw,note);state.records.unshift(record);persist();await finishLinkRecord(record);track('record_saved',{recordId:record.id,type:record.type})}else{await new Promise(r=>setTimeout(r,700));const record=genericRecord(state.captureType,raw,note);state.records.unshift(record);track('record_saved',{recordId:record.id,type:record.type});renderAll();openRecord(record.id,{trackOpen:false});toast('새 기록을 저장했어요.')}}finally{$('#analyzing').classList.remove('active');button.disabled=false;button.removeAttribute('aria-busy')}}
function mergeDuplicate(){const r=state.records.find(x=>x.id===state.pendingDuplicateId),note=$('#duplicate-note').value.trim();if(!note)return toast('이번에 떠오른 생각을 적어주세요.');r.thought=r.thought?`${r.thought}\n${note}`:note;r.savedAt=todayIso();r.capturedAt=new Date().toISOString();track('thought_saved',{recordId:r.id,type:r.type});closeSheets();renderAll();openRecord(r.id,{trackOpen:false});toast('중복 저장 없이 새 생각만 합쳤어요.')}
function openTopicEdit(){const r=state.records.find(x=>x.id===state.currentId),all=topicCounts().map(([t])=>t);$('#topic-check-list').innerHTML=all.map(t=>`<label><input type="checkbox" value="${esc(t)}" ${r.topics.includes(t)?'checked':''}><span>${esc(t)}</span></label>`).join('');$('#new-topic').value='';openSheet('#topic-edit-sheet')}
function saveRecordTopics(){const r=state.records.find(x=>x.id===state.currentId),picked=$$('#topic-check-list input:checked').map(i=>i.value),newTopic=$('#new-topic').value.trim();if(newTopic&&!picked.includes(newTopic))picked.push(newTopic);if(!picked.length)return toast('주제를 하나 이상 선택해 주세요.');r.topics=picked;persist();closeSheets();renderAll();openRecord(r.id,{trackOpen:false});toast('주제 연결을 저장했어요.')}
function fillTopicSelects(){const topics=topicCounts().map(([t])=>t);['#rename-topic-select','#merge-from','#merge-to'].forEach(id=>$(id).innerHTML=topics.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join(''))}
function renameTopic(){const from=$('#rename-topic-select').value,to=$('#rename-topic-input').value.trim();if(!to)return toast('새 이름을 입력해 주세요.');state.records.forEach(r=>r.topics=r.topics.map(t=>t===from?to:t).filter((t,i,a)=>a.indexOf(t)===i));persist();fillTopicSelects();renderAll();toast(`‘${from}’을 ‘${to}’로 바꿨어요.`)}
function mergeTopics(){const from=$('#merge-from').value,to=$('#merge-to').value;if(from===to)return toast('서로 다른 주제를 선택해 주세요.');state.records.forEach(r=>{if(r.topics.includes(from)){r.topics=r.topics.filter(t=>t!==from);if(!r.topics.includes(to))r.topics.push(to)}});persist();fillTopicSelects();renderAll();toast(`‘${from}’ 기록을 ‘${to}’에 합쳤어요.`)}
async function handleImage(file){if(!file)return;$('#image-file-name').textContent=`${file.name} · 문자 읽는 중…`;$('#image-extracted').value='';if(window.Tesseract){try{const result=await Tesseract.recognize(file,'kor+eng');$('#image-extracted').value=result.data.text.trim();$('#image-file-name').textContent=`${file.name} · 문자 인식 완료`;toast('이미지에서 읽은 문장을 확인해 주세요.');return}catch{}}$('#image-file-name').textContent=`${file.name} · 자동 인식 미지원`;$('#image-extracted').placeholder='이 환경에서는 자동 문자 인식이 어려워요. 중요한 문장을 직접 적어주세요.'}
async function toggleVoice(){const button=$('#voice-button');if(state.mediaRecorder?.state==='recording'){state.mediaRecorder.stop();state.recognition?.stop();button.classList.remove('recording');button.querySelector('strong').textContent='녹음 완료';$('#voice-status').textContent='재생하고 변환된 문장을 확인해 주세요.';return}try{state.mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});state.voiceChunks=[];state.mediaRecorder=new MediaRecorder(state.mediaStream);state.mediaRecorder.ondataavailable=e=>state.voiceChunks.push(e.data);state.mediaRecorder.onstop=()=>{const blob=new Blob(state.voiceChunks,{type:'audio/webm'}),url=URL.createObjectURL(blob),audio=$('#voice-preview');audio.src=url;audio.classList.remove('hidden');state.mediaStream.getTracks().forEach(t=>t.stop())};state.mediaRecorder.start();const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(Recognition){state.recognition=new Recognition();state.recognition.lang='ko-KR';state.recognition.continuous=true;state.recognition.interimResults=true;state.recognition.onresult=e=>{$('#voice-transcript').value=[...e.results].map(r=>r[0].transcript).join(' ')};state.recognition.start()}button.classList.add('recording');button.querySelector('strong').textContent='듣고 있어요… 다시 누르면 완료';$('#voice-status').textContent=Recognition?'말한 내용을 함께 글로 바꾸고 있어요.':'녹음 중이에요. 문자 변환은 직접 확인해 주세요.'}catch{$('#voice-status').textContent='마이크를 사용할 수 없어요. 아래에 내용을 직접 적어도 됩니다.';toast('마이크 권한을 확인해 주세요.')}}
function chooseRole(role){const detailWasOpen=$('#detail-view').classList.contains('active');state.role=role;persist();$('#profile-initial').textContent=role[0];$$('.role-grid button').forEach(b=>{const selected=b.dataset.role===role;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});toast(`${role} 관점의 질문으로 바꿨어요.`);if(detailWasOpen&&state.currentId)openRecord(state.currentId,{trackOpen:false})}
function renderVault(){const json=JSON.stringify({records:state.records,outputs:state.outputs,role:state.role,resurface:state.resurface});$('#vault-count').textContent=`기록 ${state.records.length}개 · 결과물 ${state.outputs.length}개`;$('#vault-size').textContent=`${Math.max(1,Math.ceil(new Blob([json]).size/1024))} KB`;$('#last-backup').textContent=state.lastBackupAt?`마지막 백업: ${new Date(state.lastBackupAt).toLocaleString('ko-KR')}`:'아직 내려받은 백업이 없어요.'}
function openDataVault(){closeSheets();renderVault();$('#vault-status').textContent='';setTimeout(()=>openSheet('#data-vault-sheet'),80)}
function exportBackup(){const data={product:'MEMOIVE',version:11,exportedAt:new Date().toISOString(),records:state.records,outputs:state.outputs,analytics:state.analytics,role:state.role,resurface:state.resurface,reminderFrequency:state.reminderFrequency,reminderTime:state.reminderTime},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`memoive-backup-${TODAY}.json`;link.click();URL.revokeObjectURL(url);state.lastBackupAt=data.exportedAt;persist();renderVault();$('#vault-status').textContent='기록과 결과물을 백업했어요.'}
async function importBackup(file){if(!file)return;try{const data=DataTools.validateBackup(await file.text()),beforeRecords=state.records.length,beforeOutputs=state.outputs.length;state.records=DataTools.mergeRecords(state.records,data.records);state.outputs=DataTools.mergeOutputs(state.outputs,data.outputs);state.analytics=DataTools.mergeAnalytics(state.analytics,data.analytics);if(data.role)state.role=data.role;state.resurface=data.resurface;state.reminderFrequency=data.reminderFrequency;state.reminderTime=data.reminderTime;persist();renderAll();renderVault();$('#vault-status').textContent=`새 기록 ${state.records.length-beforeRecords}개, 결과물 ${state.outputs.length-beforeOutputs}개를 합쳤어요.`}catch(error){$('#vault-status').textContent=error.message||'백업 파일을 읽지 못했어요.'}finally{$('#import-backup').value=''}}
function updateNetwork(){const online=navigator.onLine,status=$('#network-status');status.textContent=online?'온라인':'오프라인 · 주소부터 저장';status.classList.toggle('offline',!online)}
async function retryPendingLinks(){if(state.retrying||!navigator.onLine)return;const pending=state.records.filter(record=>record.fetchStatus==='failed'&&record.url);if(!pending.length)return;state.retrying=true;let restored=0;for(const record of pending){try{record.fetchStatus='reading';await readLink(record);restored++}catch{failedLinkRecord(record)}}state.retrying=false;persist();renderAll();if(restored)toast(`${restored}개 원문을 다시 읽었어요.`)}
function notificationStatus(){const rhythm=state.reminderFrequency==='daily'?'매일':state.reminderFrequency==='1'?'주 1회':'주 3회';if(!state.resurface)return'질문 리듬을 껐어요. 기록은 언제든 남길 수 있어요.';if(!('Notification'in window))return`${rhythm} · 앱 안에서만 질문을 보여드려요.`;return Notification.permission==='granted'?`${rhythm} · ${state.reminderTime} 이후 앱을 열면 기기 알림도 받을 수 있어요.`:Notification.permission==='denied'?`${rhythm} · 기기 알림은 차단되어 앱 안에서만 보여드려요.`:`${rhythm} · 켜면 기기 알림 권한을 한 번 확인해요.`}
async function notifyDueRecord(force=false){const nowTime=new Date().toTimeString().slice(0,5);if(!('Notification'in window)||Notification.permission!=='granted'||!state.resurface||(!force&&(!isRhythmDay()||nowTime<state.reminderTime||state.lastNotified===TODAY)))return;const record=state.records.find(item=>item.revisitOn&&item.revisitOn<=TODAY);if(!record)return;const registration=await navigator.serviceWorker?.ready;await registration?.showNotification('오늘 다시 볼 기록이 있어요',{body:record.title,tag:`memoive-${TODAY}`,icon:'./icon.svg'});state.lastNotified=TODAY;persist()}
async function enableNotifications(){if(!('Notification'in window))return toast('이 브라우저에서는 알림을 사용할 수 없어요.');const permission=await Notification.requestPermission();$('#notification-status').textContent=notificationStatus();if(permission==='granted'){await notifyDueRecord(true);toast('재발견 알림을 켰어요.')}else toast('알림은 브라우저 설정에서 다시 허용할 수 있어요.')}
async function installApp(){if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;return toast('설치 선택을 확인했어요.')}toast('브라우저 메뉴에서 ‘홈 화면에 추가’를 선택해 주세요.')}
function updateInstallVisibility(){const installed=window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true;$('#install-app')?.classList.toggle('hidden',installed)}
function renderAll(){state.records=DataTools.sortRecords(state.records);renderHome();renderLibrary();renderTopics();renderCalendar();renderInsights();renderStudio();updateNetwork();$('#today-label').textContent=TODAY_DATE.toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});$('#profile-initial').textContent=state.role[0];$$('.role-grid button').forEach(b=>{const selected=b.dataset.role===state.role;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});$('#resurface-toggle').checked=state.resurface;$('#reminder-frequency').value=state.reminderFrequency;$('#reminder-time').value=state.reminderTime;$('#notification-status').textContent=notificationStatus();updateInstallVisibility()}
