function creatorSourceOptions(selected){
  const label=record=>`<label><input type="checkbox" value="${esc(record.id)}" ${selected.has(record.id)?'checked':''}><span><strong>${DataTools.isExample(record)?'[예시] ':''}${esc(record.title)}</strong><small>${esc(record.thought||record.summary)}</small></span></label>`;
  const chosen=state.records.filter(record=>selected.has(record.id)),others=state.records.filter(record=>!selected.has(record.id));
  return chosen.map(label).join('')+(others.length?`<details class="more-sources" ${chosen.length?'':'open'}><summary>다른 기록 더 고르기 · ${others.length}개</summary>${others.map(label).join('')}</details>`:'');
}
function renderRecordProgress(record){
  const progress=DataTools.recordProgress(record,state.outputs);
  $('#record-progress').innerHTML=`<p class="eyebrow">이 영감의 다음 한 걸음</p><ol class="record-stages"><li>저장됨</li><li>${progress.hasThought?'내 생각 있음':'내 생각 선택'}</li><li>${progress.output?'결과물 저장됨':'결과물 만들기'}</li></ol><p>${progress.used?'활용 근거를 남긴 결과물이 있어요. 무엇이 달라졌는지 다시 살펴보세요.':progress.output?'이미 만든 결과물을 다시 열어 다듬거나, 어디에 썼는지 남겨보세요.':progress.hasThought?'남긴 생각을 바탕으로 첫 결과물을 만들어보세요.':'왜 남겼는지 한 줄이면 충분해요. 생각을 쓰지 않고 결과물로 넘어가도 괜찮아요.'}</p><button class="quiet-action" type="button" id="progress-thought">${progress.hasThought?'내 생각 다듬기':'내 생각 한 줄 남기기'}</button>`;
  $('#progress-thought').onclick=()=>openThought(record.id);
  $('#create-from-record').textContent=progress.output?'결과물 이어 쓰기':'결과물 만들기';
  $('#case-application').hidden=!record.applicationIdea;$('#case-application-text').textContent=record.applicationIdea||'';
}
function continueFromRecord(){
  const record=state.records.find(item=>item.id===state.currentId);if(!record)return;
  const progress=DataTools.recordProgress(record,state.outputs);
  if(progress.output)openCreator({outputId:progress.output.id});
  else{openCreator({recordIds:[record.id]});$('#output-viewpoint').value=record.thought||'';}
}
function caseRecords(){return CaseStudies.records.map(sample=>state.records.find(record=>record.id===sample.id||normalizeUrl(record.url)===normalizeUrl(sample.url))).filter(Boolean);}
function openCaseProposal(){
  const records=caseRecords();openCreator({recordIds:records.map(record=>record.id)});
  $('#output-type').value='proposal';$('#output-purpose').value=CaseStudies.proposal.purpose;$('#output-viewpoint').value=CaseStudies.proposal.viewpoint;
  applyOutputDraft(CaseStudies.proposal,records,'proposal');$('#case-proposal-note').hidden=false;
  $('#ai-status').textContent='세 사례를 바탕으로 미리 작성한 개선 제안 예시입니다. 실시간 AI 생성이 아니며, 내 생각에 맞게 수정해 주세요.';
}
$('#output-used').onchange=()=>{$('#output-use-fields').hidden=!$('#output-used').checked;};
$('#open-case-proposal').onclick=openCaseProposal;
$('#case-record-list').innerHTML=caseRecords().map(record=>recordRow(record,'case-record')).join('');bindRecordButtons();
